mapper.select:
select id, action_name as actionName, biz_key as bizKey, status, current_step_index as currentStepIndex, total_step_count as totalStepCount, attributes_json as attributesJson, last_error_code as lastErrorCode, last_error_message as lastErrorMessage, version, created_at as createdAt, updated_at as updatedAt from action_instance where status in
#{status}
and updated_at <= #{updatedBeforeOrAt} order by updated_at asc, created_at asc limit #{limit}

mapper.insert:
insert into action_instance (
    id, action_name, biz_key, status, current_step_index, total_step_count, attributes_json,
    last_error_code, last_error_message, version, created_at, updated_at
) values (
    #{id}, #{actionName}, #{bizKey}, #{status}, #{currentStepIndex}, #{totalStepCount}, #{attributesJson},
    #{lastErrorCode}, #{lastErrorMessage}, #{version}, #{createdAt}, #{updatedAt}
)
